const input=document.getElementById('input'),format=document.getElementById('format'),preview=document.getElementById('preview'),generate=document.getElementById('generate');function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function render(){const txt=input.value.trim(),f=format.value;if(f==='TXT'){preview.textContent=txt||'Nothing to preview.';return}const lines=txt.split(/\n+/).filter(Boolean);if(f==='CSV'){preview.textContent='message\n'+lines.map(x=>'"'+x.replace(/"/g,'""')+'"').join('\n');return}if(f==='HTML'){preview.textContent='<!doctype html>\n<html><body>\n'+lines.map(x=>'  <p>'+esc(x)+'</p>').join('\n')+'\n</body></html>';return}preview.textContent=JSON.stringify(lines.map((message,index)=>({index:index+1,message})),null,2)}generate.addEventListener('click',render);format.addEventListener('change',render);render();